Item.method_code:
var cuiDashboardItemTypeId = "9307EF625E31453D9CD861D10C7498C4";
var cuiDashboardPresentationConfigurationId = "0D219B97758045A98701DF82A8E52496";

Item itemPresentationConfiguration = this.newItem("ItemPresentationConfiguration", "add");
itemPresentationConfiguration.setID(this.getNewID());
itemPresentationConfiguration.setProperty("client_type", "js");
itemPresentationConfiguration.setProperty("item_type_id", cuiDashboardItemTypeId);
itemPresentationConfiguration.setProperty("item_id", this.getID());
itemPresentationConfiguration.setProperty("presentation_config_id", cuiDashboardPresentationConfigurationId);

Aras.Server.Security.Identity administratorsIdentity = Aras.Server.Security.Identity.GetByName("Administrators");
using (CCO.Permissions.GrantIdentity(administratorsIdentity))
{
	itemPresentationConfiguration = itemPresentationConfiguration.apply();
	if (itemPresentationConfiguration.isError())
	{
		return itemPresentationConfiguration;
	}
}

this.setPropertyItem("presentation", itemPresentationConfiguration);

return this;
